INSERT INTO clues (dish_id, order_index, text) VALUES
((SELECT id FROM dishes WHERE slug='acai-bowl'), 1, 'Frozen purple slush eaten with a spoon after a morning at the beach.'),
((SELECT id FROM dishes WHERE slug='acai-bowl'), 2, 'Importers began shipping the frozen pulp north around 2000, and Hawaii and California caught on first.'),
((SELECT id FROM dishes WHERE slug='acai-bowl'), 3, 'Brazil sold about 60 kilos of the pulp abroad in 1999 and more than 15,000 tonnes by 2021.'),
((SELECT id FROM dishes WHERE slug='acai-bowl'), 4, 'You blend the frozen pulp with banana until it is thick enough to hold a spoon, then cover it in granola and honey.'),
((SELECT id FROM dishes WHERE slug='acai-bowl'), 5, 'A thick violet smoothie under granola and sliced fruit, a Brazilian beach snack turned breakfast.'),
((SELECT id FROM dishes WHERE slug='pao-de-queijo'), 1, 'Golf-ball rolls, crisp outside and stretchy inside, sold by the bagful.'),
((SELECT id FROM dishes WHERE slug='pao-de-queijo'), 2, 'Cooks in the gold-mining hills of Ouro Preto baked with cassava starch in the 1700s, and cheese came later.'),
((SELECT id FROM dishes WHERE slug='pao-de-queijo'), 3, 'No wheat goes in at all, so the rolls are gluten-free and pull apart in elastic strings.'),
((SELECT id FROM dishes WHERE slug='pao-de-queijo'), 4, 'You scald cassava starch with hot milk and oil, beat in eggs and grated cheese, and shape the sticky dough into balls.'),
((SELECT id FROM dishes WHERE slug='pao-de-queijo'), 5, 'Chewy golden puffs passed around in a basket with coffee, the cheese bread of Brazil.'),
((SELECT id FROM dishes WHERE slug='picanha'), 1, 'Carved off a long skewer right at your table.'),
((SELECT id FROM dishes WHERE slug='picanha'), 2, 'Brazilian immigrants took it to Portugal in the 1990s, as mad cow fears drove diners off British beef.'),
((SELECT id FROM dishes WHERE slug='picanha'), 3, 'American and French butchers trim off the thick fat cap that this cut keeps on the grill.'),
((SELECT id FROM dishes WHERE slug='picanha'), 4, 'You skewer thick slices fat side out, season them with nothing but coarse salt, and turn them over charcoal.'),
((SELECT id FROM dishes WHERE slug='picanha'), 5, 'The prized beef at a Brazilian churrascaria, rosy slices rimmed with crackling fat.'),
((SELECT id FROM dishes WHERE slug='coxinha'), 1, 'A fried teardrop with a pointed tip, sold warm at the snack bar.'),
((SELECT id FROM dishes WHERE slug='coxinha'), 2, 'Legend says an imperial cook ran out of drumsticks for a fussy royal child and shaped dough like one.'),
((SELECT id FROM dishes WHERE slug='coxinha'), 3, 'The dough is cooked in chicken broth before it is shaped, so even the crust tastes of the bird.'),
((SELECT id FROM dishes WHERE slug='coxinha'), 4, 'You wrap the dough around shredded chicken and soft catupiry cheese, pinch it to a point, roll it in crumbs and fry it.'),
((SELECT id FROM dishes WHERE slug='coxinha'), 5, 'A crisp breaded drumstick of dough around chicken and cream cheese, Brazil''s ''little thigh''.'),
((SELECT id FROM dishes WHERE slug='brigadeiro'), 1, 'Chocolate balls in paper cups, lined up at a children''s party.'),
((SELECT id FROM dishes WHERE slug='brigadeiro'), 2, 'A confectioner made them in 1945 so women could sell them for an air force officer''s run at the presidency.'),
((SELECT id FROM dishes WHERE slug='brigadeiro'), 3, 'The candidate lost, but the sweet carrying his military rank outlived the campaign.'),
((SELECT id FROM dishes WHERE slug='brigadeiro'), 4, 'You stir condensed milk, cocoa and butter over low heat until it pulls from the pan, then roll it into balls by hand.'),
((SELECT id FROM dishes WHERE slug='brigadeiro'), 5, 'A fudgy bite rolled in chocolate sprinkles, the truffle of Brazilian birthday tables.'),
((SELECT id FROM dishes WHERE slug='moqueca'), 1, 'Brought to the table still bubbling in the pot it cooked in.'),
((SELECT id FROM dishes WHERE slug='moqueca'), 2, 'African and Portuguese cooks in Bahia shaped it, and the state still insists on palm oil and coconut milk.'),
((SELECT id FROM dishes WHERE slug='moqueca'), 3, 'A rival state uses olive oil and annatto, and black clay pots sealed with mangrove sap.'),
((SELECT id FROM dishes WHERE slug='moqueca'), 4, 'You layer fish, tomato, onion and peppers in the pot, pour coconut milk over the top, and simmer it covered.'),
((SELECT id FROM dishes WHERE slug='moqueca'), 5, 'Fish stew stained orange by palm oil, spooned over rice with cilantro in Brazil''s northeast.'),
((SELECT id FROM dishes WHERE slug='pollo-a-la-brasa'), 1, 'Whole birds turn on spits in a charcoal oven by the front window.'),
((SELECT id FROM dishes WHERE slug='pollo-a-la-brasa'), 2, 'A Swiss resident of Lima seasoned birds with only salt in 1950, and a Swiss metalworker built the oven.'),
((SELECT id FROM dishes WHERE slug='pollo-a-la-brasa'), 3, 'The charcoal oven built to turn out bird after bird got a nickname of its own, el rotombo.'),
((SELECT id FROM dishes WHERE slug='pollo-a-la-brasa'), 4, 'You marinate a whole bird in soy sauce, cumin, garlic and chili paste, then roast it on a spit over wood coals.'),
((SELECT id FROM dishes WHERE slug='pollo-a-la-brasa'), 5, 'Peru''s rotisserie chicken, a smoky bronze quarter with thick fries and a cup of creamy green sauce.'),
((SELECT id FROM dishes WHERE slug='alfajores'), 1, 'Two crumbly rounds stuck together, sold in foil at newsstand kiosks.'),
((SELECT id FROM dishes WHERE slug='alfajores'), 2, 'Moorish cooks gave Spain the name, from an Arabic word for luxurious, and settlers carried it west.'),
((SELECT id FROM dishes WHERE slug='alfajores'), 3, 'Argentines eat around six million a day, among the most of any country.'),
((SELECT id FROM dishes WHERE slug='alfajores'), 4, 'You sandwich two cornstarch shortbread rounds around dulce de leche, then roll the edges in grated coconut.'),
((SELECT id FROM dishes WHERE slug='alfajores'), 5, 'A soft cookie sandwich oozing caramel at the seam, unwrapped with coffee across Argentina.'),
((SELECT id FROM dishes WHERE slug='carne-asada'), 1, 'Thin steaks sizzle on a backyard grill while the relatives gather.'),
((SELECT id FROM dishes WHERE slug='carne-asada'), 2, 'Ranching families in Sonora and Nuevo León grilled beef over open fire, and it became a weekend habit.'),
((SELECT id FROM dishes WHERE slug='carne-asada'), 3, 'The name doubles as the party: friends invite you to one the way Americans invite you to a barbecue.'),
((SELECT id FROM dishes WHERE slug='carne-asada'), 4, 'You soak skirt or flank steak in lime juice, garlic and salt, sear it over hot coals, and chop it on a board.'),
((SELECT id FROM dishes WHERE slug='carne-asada'), 5, 'Charred steak chopped into strips and folded into warm Mexican tortillas with onion and cilantro.'),
((SELECT id FROM dishes WHERE slug='flautas'), 1, 'Long, pencil-thin and crackling, lined up four to a plate.'),
((SELECT id FROM dishes WHERE slug='flautas'), 2, 'Cooks north and south of the border set it apart from the smaller rolled taco by its length.'),
((SELECT id FROM dishes WHERE slug='flautas'), 3, 'Each one is pinned with a toothpick to hold its tight roll in the oil, and you pull it out before biting.'),
((SELECT id FROM dishes WHERE slug='flautas'), 4, 'You roll shredded chicken tight inside a long tortilla and fry it until the shell turns stiff and golden.'),
((SELECT id FROM dishes WHERE slug='flautas'), 5, 'Mexico''s ''flutes'', crunchy rolled tortillas under sour cream, salsa verde and crumbled cheese.'),
((SELECT id FROM dishes WHERE slug='tortilla-soup'), 1, 'A brick-red bowl with a crunchy heap on top that goes soft as you eat.'),
((SELECT id FROM dishes WHERE slug='tortilla-soup'), 2, 'No one has traced its first cook, but kitchens around Mexico City make it more than most.'),
((SELECT id FROM dishes WHERE slug='tortilla-soup'), 3, 'The cook crumbles fried pasilla chile over each bowl, sometimes with bits of pork crackling.'),
((SELECT id FROM dishes WHERE slug='tortilla-soup'), 4, 'You blend roasted tomato, onion and garlic into chicken broth, simmer it, and ladle it over fried tortilla strips.'),
((SELECT id FROM dishes WHERE slug='tortilla-soup'), 5, 'Chicken broth under crisp corn strips, avocado and soft white cheese, ladled out across Mexico.'),
((SELECT id FROM dishes WHERE slug='cochinita-pibil'), 1, 'Meat lifted out of a pit in the ground, stained a deep red-orange.'),
((SELECT id FROM dishes WHERE slug='cochinita-pibil'), 2, 'Maya cooks on the Yucatán Peninsula buried it over a fire, and the original is a whole suckling pig.'),
((SELECT id FROM dishes WHERE slug='cochinita-pibil'), 3, 'Bitter Seville oranges give the marinade its bite, and a pink tangle of pickled onions goes on top.'),
((SELECT id FROM dishes WHERE slug='cochinita-pibil'), 4, 'You rub pork with achiote paste and sour orange juice, wrap it in banana leaves, and roast it for hours.'),
((SELECT id FROM dishes WHERE slug='cochinita-pibil'), 5, 'Brick-red pulled pork on corn tortillas with habanero salsa, straight out of Mexico''s Yucatán.'),
((SELECT id FROM dishes WHERE slug='conchas'), 1, 'You choose it yourself with tongs and a tray at the bakery.'),
((SELECT id FROM dishes WHERE slug='conchas'), 2, 'Popular belief credits French bakers in colonial Mexico, and the first recorded recipe dates to 1820.'),
((SELECT id FROM dishes WHERE slug='conchas'), 3, 'A crackly sugar crust scored in curved grooves sits on top and flakes off at the first bite.'),
((SELECT id FROM dishes WHERE slug='conchas'), 4, 'You cover a soft yeast bun with a paste of flour, sugar and butter, then press a pattern into it before baking.'),
((SELECT id FROM dishes WHERE slug='conchas'), 5, 'Mexico''s sweet ''shell'', a round bun with a striped pink or chocolate top, eaten with coffee.'),
((SELECT id FROM dishes WHERE slug='jamaican-beef-patty'), 1, 'A golden half-moon pastry slid into a paper bag at the counter.'),
((SELECT id FROM dishes WHERE slug='jamaican-beef-patty'), 2, 'In 1985 Canadian meat inspectors objected to its name, and vendors won by adding their island to the label.'),
((SELECT id FROM dishes WHERE slug='jamaican-beef-patty'), 3, 'Turmeric or egg wash dyes the flaky crust yellow, and people eat it tucked inside soft coco bread.'),
((SELECT id FROM dishes WHERE slug='jamaican-beef-patty'), 4, 'You fill rounds of short pastry with ground beef spiced with scotch bonnet, thyme and onion, then crimp and bake them.'),
((SELECT id FROM dishes WHERE slug='jamaican-beef-patty'), 5, 'Jamaica''s bright yellow turnover, flaky and peppery, eaten on the run for lunch.'),
((SELECT id FROM dishes WHERE slug='oxtail-stew'), 1, 'Bones you pick up and suck clean, in gravy dark enough to stain rice.'),
((SELECT id FROM dishes WHERE slug='oxtail-stew'), 2, 'Cooks across the Caribbean braise it and serve it with white rice, or lately with rice and peas.'),
((SELECT id FROM dishes WHERE slug='oxtail-stew'), 3, 'Butter beans go in near the end and turn soft enough to fall apart into the sauce.'),
((SELECT id FROM dishes WHERE slug='oxtail-stew'), 4, 'You brown the pieces hard, then braise them for hours with allspice, thyme, scotch bonnet and onion.'),
((SELECT id FROM dishes WHERE slug='oxtail-stew'), 5, 'Glossy braised tail pieces, the meat sliding off the bone, in dark Jamaican gravy.'),
((SELECT id FROM dishes WHERE slug='arroz-con-gandules'), 1, 'A big pot of yellow rice that has to be on the table at Christmas.'),
((SELECT id FROM dishes WHERE slug='arroz-con-gandules'), 2, 'It shares national-dish status on the island with roast pork, and families serve the two at holidays.'),
((SELECT id FROM dishes WHERE slug='arroz-con-gandules'), 3, 'The prize is the crust of rice stuck to the bottom of the pot, scraped up and fought over.'),
((SELECT id FROM dishes WHERE slug='arroz-con-gandules'), 4, 'You fry sofrito in annatto oil, add pigeon peas, olives and pork, then cook the rice in it until the liquid is gone.'),
((SELECT id FROM dishes WHERE slug='arroz-con-gandules'), 5, 'Puerto Rico''s holiday rice, golden orange and dotted with green peas and olives.'),
((SELECT id FROM dishes WHERE slug='picadillo'), 1, 'A weeknight skillet of minced meat that ends up on rice or in a pastry.'),
((SELECT id FROM dishes WHERE slug='picadillo'), 2, 'Spain carried it to its colonies before the 1800s, and cooks from Mexico to the Philippines make their own.'),
((SELECT id FROM dishes WHERE slug='picadillo'), 3, 'Sweet raisins and salty green olives land in the same spoonful, a pairing that surprises first-timers.'),
((SELECT id FROM dishes WHERE slug='picadillo'), 4, 'You brown ground beef with onion, pepper and garlic, then simmer it with tomato, cumin, olives and capers.'),
((SELECT id FROM dishes WHERE slug='picadillo'), 5, 'Cuba''s savory minced beef, spooned over white rice and also stuffed into fried potato balls.'),
((SELECT id FROM dishes WHERE slug='mangu'), 1, 'A smooth breakfast mash under a tangle of pink, sharp-tasting onions.'),
((SELECT id FROM dishes WHERE slug='mangu'), 2, 'Enslaved West Africans carried their pounded starches to the island, and this mash grew out of that.'),
((SELECT id FROM dishes WHERE slug='mangu'), 3, 'It comes with ''the three hits'': fried cheese, fried eggs and fried salami on the side.'),
((SELECT id FROM dishes WHERE slug='mangu'), 4, 'You boil green plantains until soft, then mash them with butter and some of the cooking water until smooth.'),
((SELECT id FROM dishes WHERE slug='mangu'), 5, 'The Dominican Republic''s breakfast of mashed green plantains, pale and buttery under red onions.'),
((SELECT id FROM dishes WHERE slug='griot'), 1, 'Crisp brown cubes passed around at a party, with fiery slaw beside them.'),
((SELECT id FROM dishes WHERE slug='griot'), 2, 'Hosts set it out at parties, and many on the island name it a national dish beside red beans and rice.'),
((SELECT id FROM dishes WHERE slug='griot'), 3, 'The pork is cooked twice: braised soft in citrus first, then fried until the edges crunch.'),
((SELECT id FROM dishes WHERE slug='griot'), 4, 'You marinate pork shoulder in sour orange, lime and a pounded herb paste called epis, and save the juices for sauce.'),
((SELECT id FROM dishes WHERE slug='griot'), 5, 'Crunchy fried pork beside pikliz, the vinegary Haitian cabbage slaw hot with scotch bonnet.'),
((SELECT id FROM dishes WHERE slug='doubles'), 1, 'Bought at dawn from a roadside cart and eaten standing up.'),
((SELECT id FROM dishes WHERE slug='doubles'), 2, 'Emamool Deen and his wife Raheeman began selling it in Princes Town in 1936.'),
((SELECT id FROM dishes WHERE slug='doubles'), 3, 'It has a hangover-cure reputation, and the vendor asks how much pepper sauce you want.'),
((SELECT id FROM dishes WHERE slug='doubles'), 4, 'You fry two rounds of soft turmeric dough and spoon curried chickpeas between them with tamarind and cucumber chutney.'),
((SELECT id FROM dishes WHERE slug='doubles'), 5, 'Trinidad''s street breakfast: two soft fried flatbreads holding curried chickpeas.');
